72:  if(!r.ok)throw Error(`Model server returned HTTP ${r.status}`);
73:  const d=await r.json();let text=d.choices?.[0]?.message?.content||'';
74:  text=text.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
75:  const obj=JSON.parse(text);
76:  if(!Array.isArray(obj.files)||!obj.files.length)throw Error('Model response did not contain pack files.');
77:  const files=obj.files.map(f=>({path:safeModelPath(f?.path),content:typeof f?.content==='string'?f.content:JSON.stringify(f?.content,null,2)})).filter(f=>f.path);
78:  if(!files.length)throw Error('Model response contained no safe .json, .txt, or .lang files.');
79:  return {name:obj.name||'AI generated add-on',description:prompt,icon:'✦',files,id:slug(obj.name||prompt)}
80: }
